mapper.select:
SELECT h.id AS hypervisor_id, h.hypervisor_status AS status, h.availability_zone, h.hostname,
       h.vcpus AS total_vcpu, h.reserved_vcpu, h.used_vcpus AS used_vcpu,
       h.ram AS total_memory_gb, h.reserved_memory_gb, h.used_ram AS used_memory_gb,
       h.disk AS total_disk_gb, h.reserved_disk_gb, h.used_disk AS used_disk_gb,
       h.gpus AS total_gpu, h.reserved_gpu, h.used_gpus AS used_gpu, h.resource_version
FROM hypervisor_host h
WHERE h.hypervisor_status = 'ACTIVE'
  AND h.available_vcpu >= #{vcpus}
  AND h.available_memory_gb >= #{memoryGb}
  AND h.available_disk_gb >= #{diskGb}
  AND h.available_gpu >= #{gpuCount}

  AND h.availability_zone = #{availabilityZone}


  AND h.region_id = #{regionId}


  AND h.hypervisor_type = #{hypervisorType}



  AND CAST(h.hostname AS BINARY) = CAST(#{hostname} AS BINARY)

ORDER BY h.id
LIMIT #{limit}
